steps.body:
The sets here are `map[string]struct{}` maps, so membership is checked with the comma-ok form, `_, ok := b[k]`. Set operations are short loops. Range over one set and decide, key by key, what goes into a new set.

- **Intersection** (in both): loop over `a` and keep each key that `b` also has.
- **Union** (in either): add every key of `a`, then every key of `b`, into a new set. Repeats collapse on their own.
- **Difference** (`a` but not `b`): loop over `a` and keep each key that `b` lacks.

```go harness
package main

import (
	"fmt"
	"sort"
)

func main() {
	a := map[string]struct{}{"Ana": {}, "Ben": {}, "Cleo": {}, "Dev": {}}
	b := map[string]struct{}{"Ben": {}, "Dev": {}, "Eli": {}}
	{{code}}
	keys := []string{}
	for k := range both {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	fmt.Println(keys)
}
```

```go
both := map[string]struct{}{}
for k := range a {
	if _, ok := b[k]; ok {
		both[k] = struct{}{}
	}
}
```

Build a new set instead of deleting from `a`. A map is shared when you assign or pass it, so changing it in place would change the caller's set too.

Ranging over a map visits keys in random order, so never print a set from inside the loop. Collect the keys into a slice, call `sort.Strings`, and print that. A small `sortedKeys` helper keeps this tidy, and a `toSet` helper turns a slice into a set.

example.code:
package main

import (
	"fmt"
	"sort"
)

func toSet(items []string) map[string]struct{} {
	set := map[string]struct{}{}
	for _, item := range items {
		set[item] = struct{}{}
	}
	return set
}

func sortedKeys(set map[string]struct{}) []string {
	keys := make([]string, 0, len(set))
	for k := range set {
		keys = append(keys, k)
	}
	sort.Strings(keys) // map order is random, so sort before printing
	return keys
}

func main() {
	chess := toSet([]string{"Ana", "Ben", "Cleo", "Dev"})
	music := toSet([]string{"Ben", "Dev", "Eli"})

	both := map[string]struct{}{}
	for name := range chess {
		if _, ok := music[name]; ok {
			both[name] = struct{}{}
		}
	}

	either := map[string]struct{}{}
	for name := range chess {
		either[name] = struct{}{}
	}
	for name := range music {
		either[name] = struct{}{}
	}

	chessOnly := map[string]struct{}{}
	for name := range chess {
		if _, ok := music[name]; !ok {
			chessOnly[name] = struct{}{}
		}
	}

	fmt.Println("Both:", sortedKeys(both))
	fmt.Println("Either:", sortedKeys(either))
	fmt.Println("Chess only:", sortedKeys(chessOnly))
}

