package main

import (
	"fmt"
	"sort"
)

func toSet(items []string) map[string]struct{} {
	set := map[string]struct{}{}
	for _, item := range items {
		set[item] = struct{}{}
	}
	return set
}

func sortedKeys(set map[string]struct{}) []string {
	keys := make([]string, 0, len(set))
	for k := range set {
		keys = append(keys, k)
	}
	sort.Strings(keys) // map order is random, so sort before printing
	return keys
}

func main() {
	alice := toSet([]string{"go", "sql", "docker", "rust"})
	bob := toSet([]string{"sql", "python", "go"})

	onlyAlice := map[string]struct{}{}
	for skill := range alice {
		if _, ok := bob[skill]; !ok {
			onlyAlice[skill] = struct{}{}
		}
	}

	combined := map[string]struct{}{}
	for skill := range alice {
		combined[skill] = struct{}{}
	}
	for skill := range bob {
		combined[skill] = struct{}{}
	}

	fmt.Println("Only Alice:", sortedKeys(onlyAlice))
	fmt.Println("Combined:", len(combined))
}
